// One item per Apollo page, so the HTTP node paginates without a loop node.
const icp = $input.first().json;
const pages = Math.max(1, Number(icp.pages || 1));
const out = [];
for (let p = 1; p <= pages; p++) {
  out.push({ json: Object.assign({}, icp, { page: p }) });
}
return out;

// Flatten Apollo pages into the shared lead object, and dedupe inside this run.
const slug = (s) => String(s || '')
  .toLowerCase()
  .split('')
  .map((c) => ((c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') ? c : '-'))
  .join('')
  .split('-')
  .filter(Boolean)
  .join('-');

const seen = new Set();
const out = [];

for (const item of $input.all()) {
  const people = item.json.people || [];
  for (const p of people) {
    const org = p.organization || {};
    let domain = String(org.website_url || '').toLowerCase();
    domain = domain.split('//').pop().split('/')[0];
    if (domain.startsWith('www.')) domain = domain.slice(4);
    if (!domain) continue;

    const rawEmail = String(p.email || '');
    const locked = rawEmail === '' || rawEmail.includes('email_not_unlocked');
    const lead_id = slug(domain) + '-' + slug((p.first_name || '') + ' ' + (p.last_name || ''));
    if (seen.has(lead_id)) continue;
    seen.add(lead_id);

    out.push({ json: {
      lead_id: lead_id,
      first_name: p.first_name || '',
      last_name: p.last_name || '',
      title: p.title || '',
      company: org.name || '',
      domain: domain,
      linkedin_url: p.linkedin_url || '',
      email: locked ? '' : rawEmail,
      email_status: 'unknown',
      email_source: locked ? '' : 'apollo',
      country: p.country || '',
      industry: org.industry || '',
      size_hint: org.estimated_num_employees ? String(org.estimated_num_employees) + ' staff' : '',
      fit_score: null,
      fit_reason: '',
      stage: 'new',
      built_by: '01-icp-list-builder'
    }});
  }
}

return out;

// Fold the verifier verdict back onto the lead. A verifier failure leaves the lead at
// 'unknown' rather than dropping it - a dead verifier must not silently empty the list.
const map = { valid: 'valid', catchall: 'risky', unknown: 'unknown', disposable: 'invalid', invalid: 'invalid' };
const verdicts = $input.all();
const leads = $('has an email?').all();
const out = [];

for (let i = 0; i < verdicts.length; i++) {
  const lead = (leads[i] && leads[i].json) || {};
  const result = String((verdicts[i].json || {}).result || 'unknown');
  out.push({ json: Object.assign({}, lead, {
    email_status: map[result] || 'unknown',
    stage: 'enriched'
  })});
}

return out;

// No email from Apollo. Keep the row and flag it, so template 14 can enrich it.
return $input.all().map((item) => ({ json: Object.assign({}, item.json, {
  email_status: 'unknown',
  email_source: '',
  stage: 'new',
  needs_enrichment: true
})}));
